export function minutesUntilRotten(grid) {
  const a=grid.map(row=>row.slice()),q=[];let fresh=0,head=0;
  for(let r=0;r<a.length;r++)for(let c=0;c<a[r].length;c++){if(a[r][c]===2)q.push([r,c,0]);if(a[r][c]===1)fresh++;}
  let minutes=0;
  while(head<q.length){const [r,c,t]=q[head++];for(const [dr,dc] of [[1,0],[-1,0],[0,1],[0,-1]]){
    const nr=r+dr,nc=c+dc;
    if(nr<0||nr>=a.length||nc<0||nc>=a[nr].length||a[nr][nc]!==1)continue;
    a[nr][nc]=2;fresh--;minutes=Math.max(minutes,t+1);q.push([nr,nc,t+1]);
  }}
  return fresh? -1:minutes;
}
